descriptor.templateCss:
.samsung-menu-widget {
  display: flex;
  height: 100%;
  font-family: Arial, sans-serif;
}

/* Left Sidebar Styling */
.sidebar {
  background-color: #1e3a5f;  /* Dark blue background */
  width: 25%;
  padding: 20px;
  box-sizing: border-box;
  color: #fff;
}

.sidebar ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.sidebar li {
  padding: 10px;
  cursor: pointer;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
}

.sidebar li.active,
.sidebar li:hover {
  background-color: #2c5371;  /* Lighter blue on hover/active */
}

/* Right Main Content Styling */
.menu-content {
  flex: 1;
  background-color: #f0f8ff;  /* Light blue background */
  padding: 20px;
  box-sizing: border-box;
}

.menu-content h2 {
  color: #1e3a5f;
  margin-bottom: 15px;
}

.menu-items {
  display: flex;
  flex-direction: column;
}

.menu-item {
  margin-bottom: 10px;
}

.menu-item label {
  display: block;
  margin-bottom: 5px;
  color: #1e3a5f;
}

.menu-item input {
  width: 100%;
  padding: 8px;
  box-sizing: border-box;
}

descriptor.controllerScript:
self.onInit = function() {
    // Define the menu sections with items
    self.ctx.$scope.sections = [
        { 
            name: 'Home', 
            items: [
                { label: 'Welcome Message', placeholder: 'Enter message', value: '' },
                { label: 'Date Format', placeholder: 'MM/DD/YYYY', value: '' }
            ]
        },
        { 
            name: 'News', 
            items: [
                { label: 'Headline', placeholder: 'Enter headline', value: '' },
                { label: 'Ticker Speed', placeholder: 'Enter speed', value: '' }
            ]
        },
        { 
            name: 'Settings', 
            items: [
                { label: 'Brightness', placeholder: '0-100', value: '' },
                { label: 'Volume', placeholder: '0-100', value: '' }
            ]
        }
    ];

    // Set the default selected section
    self.ctx.$scope.selectedSection = self.ctx.$scope.sections[0];

    // Function to change the selected section
    self.ctx.$scope.selectSection = function(section) {
        self.ctx.$scope.selectedSection = section;
        self.ctx.$scope.$applyAsync();
    };
};
